<script setup>
import { computed, ref } from 'vue';

const props = defineProps({ items: { type: Array, default: () => [] }, reproduciendoId: { type: [Number, String], default: null }, completado: { type: Boolean, default: false } });
const emit = defineEmits(['reproducir', 'hablar', 'practicar']);

const leccion = ref(1);
const actorId = ref('she');
const receptorId = ref('me');
const duenoId = ref('she');
const objetoId = ref('laptop');
const retoActual = ref(0);
const respuestaElegida = ref(null);
const aciertos = ref(new Set());

const personas = [
  { id: 'i', icono: '🙋', nombre: 'yo', subject: 'I', object: 'me', adjective: 'my', possessive: 'mine' },
  { id: 'you', icono: '👉', nombre: 'tú / usted', subject: 'you', object: 'you', adjective: 'your', possessive: 'yours' },
  { id: 'he', icono: '👨', nombre: 'él', subject: 'he', object: 'him', adjective: 'his', possessive: 'his' },
  { id: 'she', icono: '👩', nombre: 'ella', subject: 'she', object: 'her', adjective: 'her', possessive: 'hers' },
  { id: 'it', icono: '🤖', nombre: 'eso', subject: 'it', object: 'it', adjective: 'its', possessive: null },
  { id: 'we', icono: '👥', nombre: 'nosotros', subject: 'we', object: 'us', adjective: 'our', possessive: 'ours' },
  { id: 'they', icono: '👨‍👩‍👧', nombre: 'ellos / ellas', subject: 'they', object: 'them', adjective: 'their', possessive: 'theirs' },
];
const objetos = [
  { id: 'laptop', nombre: 'laptop', icono: '💻' }, { id: 'phone', nombre: 'phone', icono: '📱' },
  { id: 'keys', nombre: 'keys', icono: '🔑' }, { id: 'backpack', nombre: 'backpack', icono: '🎒' },
];
const actor = computed(() => personas.find((item) => item.id === actorId.value));
const receptor = computed(() => personas.find((item) => item.object === receptorId.value));
const dueno = computed(() => personas.find((item) => item.id === duenoId.value));
const objeto = computed(() => objetos.find((item) => item.id === objetoId.value));
const fraseAccion = computed(() => `${capitalizar(actor.value.subject)} sent the file to ${receptor.value.object}.`);
const frasePosesivaAdj = computed(() => `This is ${dueno.value.adjective} ${objeto.value.nombre}.`);
const frasePosesivaPron = computed(() => dueno.value.possessive ? `The ${objeto.value.nombre} is ${dueno.value.possessive}.` : `It has its own ${objeto.value.nombre}.`);

const retos = [
  { icono: '📨', pista: 'Maya envió el archivo. Maya hace la acción.', frase: '___ sent the file this morning.', respuesta: 'She', opciones: ['She','Her','Hers','Their'], explicacion: 'She es pronombre sujeto: va antes del verbo.' },
  { icono: '🛍️', pista: 'Alex me ayudó a mí.', frase: 'Alex helped ___ with the bags.', respuesta: 'me', opciones: ['I','my','mine','me'], explicacion: 'Me recibe la acción y va después del verbo.' },
  { icono: '💻', pista: 'La laptop pertenece a ella y el sustantivo aparece.', frase: 'This is ___ laptop.', respuesta: 'her', opciones: ['she','her','hers','him'], explicacion: 'Her funciona como adjetivo posesivo antes de laptop.' },
  { icono: '🎒', pista: 'La mochila es nuestra; no repetimos “backpack”.', frase: 'That backpack is ___.', respuesta: 'ours', opciones: ['our','us','we','ours'], explicacion: 'Ours reemplaza al sustantivo: no lleva una palabra después.' },
  { icono: '👥', pista: 'Hablamos con ellos.', frase: 'We talked to ___ after class.', respuesta: 'them', opciones: ['they','their','theirs','them'], explicacion: 'Después de to necesitamos el pronombre objeto them.' },
  { icono: '🔑', pista: 'Las llaves pertenecen a ti.', frase: 'Are these keys ___?', respuesta: 'yours', opciones: ['your','you','yours','mine'], explicacion: 'Yours aparece solo porque keys ya se mencionó.' },
];
const reto = computed(() => retos[retoActual.value]);
const respuestaCorrecta = computed(() => respuestaElegida.value === reto.value.respuesta);
const totalAciertos = computed(() => aciertos.value.size);

function capitalizar(texto) { return texto.charAt(0).toUpperCase() + texto.slice(1); }
function normalizar(texto) { return String(texto || '').toLowerCase().replace(/[^a-z]/g, ''); }
function escuchar(texto) { const referencia = props.items.find((item) => normalizar(item.texto_en) === normalizar(texto)); if (referencia?.audio_key) emit('reproducir', referencia); else emit('hablar', texto, 1); }
function responder(opcion) { respuestaElegida.value = opcion; if (opcion === reto.value.respuesta) { const nuevos = new Set(aciertos.value); nuevos.add(retoActual.value); aciertos.value = nuevos; } }
function siguienteReto() { retoActual.value = (retoActual.value + 1) % retos.length; respuestaElegida.value = null; }
</script>

<template>
  <section class="pronoun-lesson">
    <aside class="pronoun-summary"><header><span>🎭</span><div><small>MAPA DE ROLES</small><h2>La misma persona cambia según su trabajo</h2></div></header><p><b>Sujeto</b> hace la acción, <b>objeto</b> la recibe. El posesivo va antes del objeto (<i>my laptop</i>) o lo reemplaza (<i>mine</i>).</p><div class="pronoun-table"><span>Sujeto</span><span>Objeto</span><span>Antes de objeto</span><span>Reemplaza objeto</span><template v-for="persona in personas" :key="persona.id"><b>{{ persona.subject }}</b><b>{{ persona.object }}</b><b>{{ persona.adjective }}</b><b>{{ persona.possessive || '—' }}</b></template></div></aside>
    <nav class="pronoun-tabs"><button v-for="numero in 3" :key="numero" :class="{ active: leccion === numero }" @click="leccion = numero"><b>0{{ numero }}</b><span>{{ numero === 1 ? 'Acción y receptor' : numero === 2 ? '¿De quién es?' : 'Elegí la forma' }}</span><small>{{ numero === 1 ? 'subject vs. object' : numero === 2 ? 'my vs. mine' : 'Reto de roles' }}</small></button></nav>

    <section v-if="leccion === 1" class="pronoun-panel"><header><small>PRONOMBRES 1</small><h3>Director de la escena</h3><p>Elegí quién hace la acción y quién la recibe.</p></header><div class="action-lab"><div><span class="role-label">1 · ¿Quién actúa?</span><div class="person-options"><button v-for="persona in personas" :key="persona.id" :class="{ active: actorId === persona.id }" @click="actorId = persona.id"><span>{{ persona.icono }}</span><b>{{ persona.subject }}</b></button></div></div><div><span class="role-label">2 · ¿Quién recibe?</span><div class="person-options"><button v-for="persona in personas" :key="persona.id" :class="{ active: receptorId === persona.object }" @click="receptorId = persona.object"><span>{{ persona.icono }}</span><b>{{ persona.object }}</b></button></div></div></div><div class="action-stage"><div><span>{{ actor.icono }}</span><small>SUJETO</small><b>{{ actor.subject }}</b></div><i>sent the file to</i><div><span>{{ receptor.icono }}</span><small>OBJETO</small><b>{{ receptor.object }}</b></div><button @click="escuchar(fraseAccion)">🔊 {{ fraseAccion }}</button></div><div class="role-rule"><span>🎬</span><p><b>{{ actor.subject }}</b> está antes del verbo porque actúa. <b>{{ receptor.object }}</b> aparece después de <i>to</i> porque recibe.</p></div></section>

    <section v-else-if="leccion === 2" class="pronoun-panel"><header><small>PRONOMBRES 2</small><h3>Taller de pertenencia</h3><p>Elegí al dueño y un objeto para comparar las dos estructuras.</p></header><div class="owner-lab"><div class="owner-options"><button v-for="persona in personas.filter((item)=>item.possessive)" :key="persona.id" :class="{ active: duenoId === persona.id }" @click="duenoId = persona.id"><span>{{ persona.icono }}</span><b>{{ persona.adjective }} / {{ persona.possessive }}</b></button></div><div class="object-options"><button v-for="item in objetos" :key="item.id" :class="{ active: objetoId === item.id }" @click="objetoId = item.id"><span>{{ item.icono }}</span>{{ item.nombre }}</button></div><div class="possession-stage"><span>{{ dueno.icono }} {{ objeto.icono }}</span><article><small>ANTES DEL SUSTANTIVO</small><strong>{{ frasePosesivaAdj }}</strong><button @click="escuchar(frasePosesivaAdj)">🔊</button></article><i>＝</i><article><small>SIN REPETIR EL SUSTANTIVO</small><strong>{{ frasePosesivaPron }}</strong><button @click="escuchar(frasePosesivaPron)">🔊</button></article></div></div><div class="possessive-warning"><span>⚠️</span><p><b>my, your, her, our</b> necesitan un sustantivo después. <b>mine, yours, hers, ours</b> aparecen solos.</p></div></section>

    <section v-else class="pronoun-panel"><header class="pronoun-challenge-head"><div><small>PRONOMBRES 3</small><h3>Elegí el rol correcto</h3><p>Usá la posición y el significado para completar la frase.</p></div><strong>{{ totalAciertos }}/{{ retos.length }}</strong></header><div class="pronoun-challenge"><span class="challenge-icon">{{ reto.icono }}</span><small>PISTA</small><h4>{{ reto.pista }}</h4><button class="challenge-phrase" @click="escuchar(reto.frase.replace('___',reto.respuesta))">{{ reto.frase }} <i>🔊</i></button><div class="pronoun-options"><button v-for="opcion in reto.opciones" :key="opcion" :class="{ correct: respuestaElegida && opcion === reto.respuesta, wrong: respuestaElegida === opcion && opcion !== reto.respuesta }" :disabled="respuestaCorrecta" @click="responder(opcion)">{{ opcion }}</button></div><div v-if="respuestaElegida" class="pronoun-feedback" :class="respuestaCorrecta?'ok':'retry'"><b>{{ respuestaCorrecta?'✓ ¡Rol correcto!':'↻ Revisá la posición de la palabra' }}</b><span>{{ reto.explicacion }}</span></div><button v-if="respuestaCorrecta" class="next-pronoun" @click="siguienteReto">Siguiente escena →</button></div></section>

    <button class="pronoun-practice" :disabled="completado" @click="emit('practicar')">{{ completado ? '✓ Ejercicios ya acreditados' : 'Practicar ejercicios del workbook →' }}</button>
  </section>
</template>

<style scoped>
