ff}.person-options button>span{font-size:1.25rem}.person-options button.active{border-color:#b24f88;background:#fff0f8}.action-stage{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:.6rem;margin-top:1rem;padding:1rem;border-radius:16px;background:linear-gradient(145deg,#fff0f8,#edf8ff);text-align:center}.action-stage>div{display:flex;flex-direction:column}.action-stage>div span{font-size:2rem}.action-stage small{font-size:.58rem;font-weight:900;color:#9a3c72}.action-stage>i{font:italic 1rem Georgia,serif}.action-stage>button{grid-column:1/-1;justify-self:center;border:0;border-radius:9px;background:#b24f88;color:#fff;padding:.5rem .7rem;font-weight:800}.role-rule,.possessive-warning{display:flex;gap:.55rem;margin-top:.75rem;padding:.65rem;border-radius:10px;background:#f8f0f7}.role-rule p,.possessive-warning p{margin:0;font-size:.75rem}.owner-lab{display:grid;gap:.65rem}.owner-options,.object-options{display:flex;flex-wrap:wrap;gap:.4rem}.owner-options button,.object-options button{display:flex;align-items:center;gap:.3rem;border:1px solid var(--color-borde);border-radius:9px;background:#fff;padding:.45rem .6rem}.owner-options button.active,.object-options button.active{border-color:#b24f88;background:#fff0f8}.possession-stage{display:grid;grid-template-columns:80px 1fr auto 1fr;align-items:center;gap:.6rem;padding:1rem;border-radius:16px;background:linear-gradient(145deg,#fff0f8,#eef8ff)}.possession-stage>span{font-size:2rem}.possession-stage article{display:flex;flex-direction:column}.possession-stage small{font-size:.58rem;font-weight:900;color:#9a3c72}.possession-stage strong{font:italic 1rem Georgia,serif}.possession-stage article button{align-self:flex-start;border:0;background:transparent}.possession-stage>i{font-style:normal}.pronoun-challenge-head{display:flex;justify-content:space-between}.pronoun-challenge-head>strong{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:#fdeaf5;color:#9a3c72}.pronoun-challenge{max-width:650px;margin:auto;padding:1.1rem;border-radius:17px;background:linear-gradient(145deg,#fff0f8,#eef8ff);text-align:center}.challenge-icon{font-size:2.8rem}.pronoun-challenge>small{display:block;font-size:.6rem;font-weight:900;color:#9a3c72}.pronoun-challenge h4{margin:.3rem}.challenge-phrase{border:0;background:transparent;font:italic 1.2rem Georgia,serif}.challenge-phrase i{font-style:normal;font-size:.8rem}.pronoun-options{display:grid;grid-template-columns:1fr 1fr;gap:.45rem;margin:1rem 0}.pronoun-options button{padding:.65rem;border:1px solid var(--color-borde);border-radius:10px;background:#fff;font-weight:800}.pronoun-options button.correct{border-color:var(--color-verde);background:var(--color-verde-suave)}.pronoun-options button.wrong{border-color:#c96543;background:#fff0ea}.pronoun-feedback{display:flex;flex-direction:column;padding:.65rem;border-radius:10px;font-size:.75rem;text-align:left}.pronoun-feedback.ok{background:var(--color-verde-suave);color:#236843}.pronoun-feedback.retry{background:#fff0ea;color:#984228}.next-pronoun{display:block;margin:.65rem 0 0 auto;border:0;border-radius:9px;background:#b24f88;color:#fff;padding:.55rem .8rem;font-weight:800}.pronoun-practice{width:100%;padding:.8rem;border:0;border-radius:var(--radio-boton);background:#b24f88;color:#fff;font-weight:800}.pronoun-practice:disabled{background:var(--color-verde)}
@media(max-width:760px){.action-lab{grid-template-columns:1fr}.possession-stage{grid-template-columns:60px 1fr}.possession-stage>i{display:none}.possession-stage article:last-child{grid-column:2}}
@media(max-width:520px){.pronoun-tabs{grid-template-columns:1fr}.person-options{grid-template-columns:repeat(4,1fr)}.action-stage{grid-template-columns:1fr}.action-stage>i{transform:rotate(90deg)}.pronoun-options{grid-template-columns:1fr}.pronoun-table>span{font-size:.52rem}.pronoun-table>b{font-size:.62rem}.pronoun-panel{padding:.75rem}}
</style>
